type:
∀ {m d u : ℕ} {a : Finset ℕ} {q_two : 2 ≤ a.card} {a_pos : ∀ b ∈ a, 0 < b} {a_lt : ∀ b ∈ a, b < u} {u_lt : u < m}
  {d_pos : 1 ≤ d} {offsets_coprime : (a.gcd id).gcd u = 1} {coprime : m.Coprime d} {m_1 d_1 u_1 : ℕ} {a_1 : Finset ℕ}
  {q_two_1 : 2 ≤ a_1.card} {a_pos_1 : ∀ b ∈ a_1, 0 < b} {a_lt_1 : ∀ b ∈ a_1, b < u_1} {u_lt_1 : u_1 < m_1}
  {d_pos_1 : 1 ≤ d_1} {offsets_coprime_1 : (a_1.gcd id).gcd u_1 = 1} {coprime_1 : m_1.Coprime d_1},
  { m := m, d := d, u := u, a := a, q_two := q_two, a_pos := a_pos, a_lt := a_lt, u_lt := u_lt, d_pos := d_pos,
        offsets_coprime := offsets_coprime, coprime := coprime } =
      { m := m_1, d := d_1, u := u_1, a := a_1, q_two := q_two_1, a_pos := a_pos_1, a_lt := a_lt_1, u_lt := u_lt_1,
